     1→// Phase 1 Week 2: Parser Optimization
     2→// 성능 최적화된 .flmd 파서 (캐싱 + 병렬 처리 준비)
     3→
     4→use std::collections::HashMap
     5→
     6→// ============================================================================
     7→// Cache Structure for Performance
     8→// ============================================================================
     9→
    10→struct ParserCache {
    11→    parsed_documents: HashMap<String, Document>,
    12→    token_cache: HashMap<String, Vec<Token>>,
    13→    cache_hits: i32,
    14→    cache_misses: i32
    15→}
    16→
    17→impl ParserCache {
    18→    fn new() -> ParserCache {
    19→        ParserCache {
    20→            parsed_documents: HashMap::new(),
    21→            token_cache: HashMap::new(),
    22→            cache_hits: 0,
    23→            cache_misses: 0
    24→        }
    25→    }
    26→
    27→    fn get_cached_document(&mut self, file_hash: String) -> Option<Document> {
    28→        if let Some(doc) = self.parsed_documents.get(&file_hash) {
    29→            self.cache_hits = self.cache_hits + 1
    30→            Some(doc.clone())
    31→        } else {
    32→            self.cache_misses = self.cache_misses + 1
    33→            None
    34→        }
    35→    }
    36→
    37→    fn cache_document(&mut self, file_hash: String, doc: Document) {
    38→        self.parsed_documents.insert(file_hash, doc)
    39→    }
    40→
    41→    fn get_cache_stats(&self) -> (i32, i32, f32) {
    42→        let total = self.cache_hits + self.cache_misses
    43→        let hit_rate = if total > 0 {
    44→            (self.cache_hits as f32) / (total as f32) * 100.0
    45→        } else {
    46→            0.0
    47→        }
    48→        (self.cache_hits, self.cache_misses, hit_rate)
    49→    }
    50→}
    51→
    52→// ============================================================================
    53→// Optimized Tokenizer (한 번의 패스로 처리)
    54→// ============================================================================
    55→
    56→struct TokenStream {
    57→    tokens: Vec<Token>,
    58→    position: usize
    59→}
    60→
    61→impl TokenStream {
    62→    fn new() -> TokenStream {
    63→        TokenStream {
    64→            tokens: Vec::new(),
    65→            position: 0
    66→        }
    67→    }
    68→
    69→    fn add_token(&mut self, token: Token) {
    70→        self.tokens.push(token)
    71→    }
    72→
    73→    fn peek(&self) -> Option<&Token> {
    74→        if self.position < self.tokens.len() {
    75→            Some(&self.tokens[self.position])
    76→        } else {
    77→            None
    78→        }
    79→    }
    80→
    81→    fn next(&mut self) -> Option<Token> {
    82→        if self.position < self.tokens.len() {
    83→            let token = self.tokens[self.position].clone()
    84→            self.position = self.position + 1
    85→            Some(token)
    86→        } else {
    87→            None
    88→        }
    89→    }
    90→
    91→    fn skip_whitespace(&mut self) {
    92→        while let Some(token) = self.peek() {
    93→            if matches!(token.type, TokenType::Blank) {
    94→                self.next()
    95→            } else {
    96→                break
    97→            }
    98→        }
    99→    }
   100→}
   101→
   102→// 최적화된 토큰화 (단일 패스)
   103→fn tokenize_optimized(content: String) -> TokenStream {
   104→    let mut stream = TokenStream::new()
   105→    let lines: Vec<&str> = content.lines().collect()
   106→    let mut line_num = 1
   107→    let mut in_code_block = false
   108→    let mut in_output_block = false
   109→
   110→    for (idx, line) in lines.iter().enumerate() {
   111→        // 블록 상태 관리
   112→        if line.starts_with("```fvlang") {
   113→            stream.add_token(Token {
   114→                type: TokenType::CodeBlockStart,
   115→                content: line.to_string(),
   116→                line: line_num,
   117→                column: 0
   118→            })
   119→            in_code_block = true
   120→        } else if line.starts_with("```output") {
   121→            stream.add_token(Token {
   122→                type: TokenType::OutputBlockStart,
   123→                content: line.to_string(),
   124→                line: line_num,
   125→                column: 0
   126→            })
   127→            in_output_block = true
   128→        } else if line.starts_with("```") && (in_code_block || in_output_block) {
   129→            stream.add_token(Token {
   130→                type: if in_code_block { TokenType::CodeBlockEnd } else { TokenType::OutputBlockEnd },
   131→                content: "```".to_string(),
   132→                line: line_num,
   133→                column: 0
   134→            })
   135→            in_code_block = false
   136→            in_output_block = false
   137→        }
   138→        // 마크다운 토큰 식별 (인라인 처리)
   139→        else if line.starts_with("# ") && !in_code_block && !in_output_block {
   140→            stream.add_token(Token {
   141→                type: TokenType::Heading1,
   142→                content: line[2..].to_string(),
   143→                line: line_num,
   144→                column: 0
   145→            })
   146→        } else if line.starts_with("## ") && !in_code_block && !in_output_block {
   147→            stream.add_token(Token {
   148→                type: TokenType::Heading2,
   149→                content: line[3..].to_string(),
   150→                line: line_num,
   151→                column: 0
   152→            })
   153→        } else if line.starts_with("### ") && !in_code_block && !in_output_block {
   154→            stream.add_token(Token {
   155→                type: TokenType::Heading3,
   156→                content: line[4..].to_string(),
   157→                line: line_num,
   158→                column: 0
   159→            })
   160→        } else if line.starts_with("- ") && !in_code_block && !in_output_block {
   161→            stream.add_token(Token {
   162→                type: TokenType::ListItem,
   163→                content: line[2..].to_string(),
   164→                line: line_num,
   165→                column: 0
   166→            })
   167→        } else if line.is_empty() {
   168→            stream.add_token(Token {
   169→                type: TokenType::Blank,
   170→                content: "".to_string(),
   171→                line: line_num,
   172→                column: 0
   173→            })
   174→        } else {
   175→            // 블록 내 줄 처리
   176→            if in_code_block {
   177→                stream.add_token(Token {
   178→                    type: TokenType::CodeLine,
   179→                    content: line.to_string(),
   180→                    line: line_num,
   181→                    column: 0
   182→                })
   183→            } else if in_output_block {
   184→                stream.add_token(Token {
   185→                    type: TokenType::OutputLine,
   186→                    content: line.to_string(),
   187→                    line: line_num,
   188→                    column: 0
   189→                })
   190→            } else {
   191→                stream.add_token(Token {
   192→                    type: TokenType::Paragraph,
   193→                    content: line.to_string(),
   194→                    line: line_num,
   195→                    column: 0
   196→                })
   197→            }
   198→        }
   199→
   200→        line_num = line_num + 1
   201→    }
   202→
   203→    stream.add_token(Token {
   204→        type: TokenType::EOF,
   205→        content: "".to_string(),
   206→        line: line_num,
   207→        column: 0
   208→    })
   209→
   210→    stream
   211→}
   212→
   213→// ============================================================================
   214→// Optimized Parser with Streaming
   215→// ============================================================================
   216→
   217→fn parse_optimized(content: String) -> Result<Document, String> {
   218→    let mut stream = tokenize_optimized(content)
   219→    let mut blocks = Vec::new()
   220→    let mut title = "Untitled".to_string()
   221→
   222→    // 타이틀 추출
   223→    if let Some(token) = stream.peek() {
   224→        if matches!(token.type, TokenType::Heading1) {
   225→            if let Some(h1_token) = stream.next() {
   226→                title = h1_token.content.clone()
   227→            }
   228→        }
   229→    }
   230→
   231→    // 블록 파싱 (스트림 기반)
   232→    while let Some(token) = stream.peek() {
   233→        match token.type {
   234→            TokenType::Heading1 => {
   235→                if let Some(h1) = stream.next() {
   236→                    blocks.push(BlockType::Heading(1, h1.content))
   237→                }
   238→            }
   239→            TokenType::Heading2 => {
   240→                if let Some(h2) = stream.next() {
   241→                    blocks.push(BlockType::Heading(2, h2.content))
   242→                }
   243→            }
   244→            TokenType::Heading3 => {
   245→                if let Some(h3) = stream.next() {
   246→                    blocks.push(BlockType::Heading(3, h3.content))
   247→                }
   248→            }
   249→            TokenType::Paragraph => {
   250→                if let Some(p) = stream.next() {
   251→                    blocks.push(BlockType::Paragraph(p.content))
   252→                }
   253→            }
   254→            TokenType::CodeBlockStart => {
   255→                stream.next()  // skip opening ```
   256→                let mut code_lines = Vec::new()
   257→                while let Some(token) = stream.peek() {
   258→                    if matches!(token.type, TokenType::CodeBlockEnd) {
   259→                        stream.next()
   260→                        break
   261→                    }
   262→                    if matches!(token.type, TokenType::CodeLine) {
   263→                        if let Some(code_token) = stream.next() {
   264→                            code_lines.push(code_token.content)
   265→                        }
   266→                    } else {
   267→                        stream.next()
   268→                    }
   269→                }
   270→                blocks.push(BlockType::CodeBlock(code_lines.join("\n")))
   271→            }
   272→            TokenType::OutputBlockStart => {
   273→                stream.next()  // skip opening ```
   274→                let mut output_lines = Vec::new()
   275→                while let Some(token) = stream.peek() {
   276→                    if matches!(token.type, TokenType::OutputBlockEnd) {
   277→                        stream.next()
   278→                        break
   279→                    }
   280→                    if matches!(token.type, TokenType::OutputLine) {
   281→                        if let Some(output_token) = stream.next() {
   282→                            output_lines.push(output_token.content)
   283→                        }
   284→                    } else {
   285→                        stream.next()
   286→                    }
   287→                }
   288→                blocks.push(BlockType::OutputBlock(output_lines.join("\n")))
   289→            }
   290→            TokenType::ListItem => {
   291→                let mut items = Vec::new()
   292→                while let Some(token) = stream.peek() {
   293→                    if matches!(token.type, TokenType::ListItem) {
   294→                        if let Some(item) = stream.next() {
   295→                            items.push(item.content)
   296→                        }
   297→                    } else {
   298→                        break
   299→                    }
   300→                }
   301→                blocks.push(BlockType::ListBlock(items))
   302→            }
   303→            TokenType::Blank => {
   304→                stream.next()
   305→            }
   306→            TokenType::EOF => {
   307→                break
   308→            }
   309→            _ => {
   310→                stream.next()
   311→            }
   312→        }
   313→    }
   314→
   315→    Ok(Document {
   316→        title: title,
   317→        blocks: blocks,
   318→        metadata: Metadata {
   319→            version: "0.2.0".to_string(),
   320→            created: "2026-03-18".to_string(),
   321→            modified: "2026-03-25".to_string()
   322→        }
   323→    })
   324→}
   325→
   326→// ============================================================================
   327→// Cached Parser with Performance Tracking
   328→// ============================================================================
   329→
   330→struct OptimizedParser {
   331→    cache: ParserCache,
   332→    parse_time_ms: f64,
   333→    token_count: i32
   334→}
   335→
   336→impl OptimizedParser {
   337→    fn new() -> OptimizedParser {
   338→        OptimizedParser {
   339→            cache: ParserCache::new(),
   340→            parse_time_ms: 0.0,
   341→            token_count: 0
   342→        }
   343→    }
   344→
   345→    fn parse_with_cache(&mut self, content: String, file_hash: String) -> Result<Document, String> {
   346→        // 캐시 확인
   347→        if let Some(cached_doc) = self.cache.get_cached_document(file_hash.clone()) {
   348→            return Ok(cached_doc)
   349→        }
   350→
   351→        // 파싱
   352→        let doc = parse_optimized(content)?
   353→
   354→        // 캐시 저장
   355→        self.cache.cache_document(file_hash, doc.clone())
   356→
   357→        Ok(doc)
   358→    }
   359→
   360→    fn get_stats(&self) -> (i32, i32, f32) {
   361→        self.cache.get_cache_stats()
   362→    }
   363→}
   364→
   365→// ============================================================================
   366→// Public API with Performance Optimization
   367→// ============================================================================
   368→
   369→fn parse_flmd_optimized(content: String) -> Result<Document, String> {
   370→    parse_optimized(content)
   371→}
   372→
   373→fn create_optimized_parser() -> OptimizedParser {
   374→    OptimizedParser::new()
   375→}
   376→
   377→// ============================================================================
   378→// Batch Processing
   379→// ============================================================================
   380→
   381→fn parse_multiple(documents: Vec<(String, String)>) -> Vec<Result<Document, String>> {
   382→    let mut results = Vec::new()
   383→    let mut parser = OptimizedParser::new()
   384→
   385→    for (file_hash, content) in documents {
   386→        match parser.parse_with_cache(content, file_hash) {
   387→            Ok(doc) => results.push(Ok(doc)),
   388→            Err(e) => results.push(Err(e))
   389→        }
   390→    }
   391→
   392→    results
   393→}
   394→
   395→// ============================================================================
   396→// Benchmarking
   397→// ============================================================================
   398→
   399→struct ParsingBenchmark {
   400→    total_time: f64,
   401→    document_count: i32,
   402→    average_time: f64,
   403→    cache_hit_rate: f32
   404→}
   405→
   406→fn benchmark_parser(documents: Vec<(String, String)>) -> ParsingBenchmark {
   407→    let mut parser = OptimizedParser::new()
   408→    let start = std::time::Instant::now()
   409→
   410→    for (file_hash, content) in &documents {
   411→        let _ = parser.parse_with_cache(content.clone(), file_hash.clone())
   412→    }
   413→
   414→    let total_time = start.elapsed().as_secs_f64() * 1000.0  // ms
   415→    let doc_count = documents.len() as i32
   416→    let avg_time = total_time / (doc_count as f64)
   417→    let (_, _, hit_rate) = parser.get_stats()
   418→
   419→    ParsingBenchmark {
   420→        total_time: total_time,
   421→        document_count: doc_count,
   422→        average_time: avg_time,
   423→        cache_hit_rate: hit_rate
   424→    }
   425→}
   426→
   427→// ============================================================================
   428→// Validation Improvements
   429→// ============================================================================
   430→
   431→fn validate_optimized(doc: Document) -> Result<Document, Vec<String>> {
   432→    let mut errors = Vec::new()
   433→
   434→    if doc.title.is_empty() {
   435→        errors.push("Document title cannot be empty".to_string())
   436→    }
   437→
   438→    if doc.blocks.is_empty() {
   439→        errors.push("Document must contain at least one block".to_string())
   440→    }
   441→
   442→    // 블록 순서 검증
   443→    let mut prev_was_code = false
   444→    for block in &doc.blocks {
   445→        match block {
   446→            BlockType::CodeBlock(_) => prev_was_code = true,
   447→            BlockType::OutputBlock(_) => {
   448→                if !prev_was_code {
   449→                    errors.push("Output block must follow code block".to_string())
   450→                }
   451→                prev_was_code = false
   452→            }
   453→            _ => prev_was_code = false
   454→        }
   455→    }
   456→
   457→    if errors.is_empty() {
   458→        Ok(doc)
   459→    } else {
   460→        Err(errors)
   461→    }
   462→}
