     4→// ============================================================================
     5→// Syntax Highlighting for FV-Lang
     6→// ============================================================================
     7→
     8→enum SyntaxType {
     9→    Keyword,        // fn, let, if, match, etc.
    10→    String,         // "..."
    11→    Number,         // 123, 3.14
    12→    Comment,        // // comment
    13→    Identifier,     // variable names
    14→    Operator,       // +, -, *, /, =
    15→    Type,           // i32, String, Vec
    16→    Punctuation     // {}, [], (), ;
    17→}
    18→
    19→struct HighlightRule {
    20→    pattern: String,
    21→    syntax_type: SyntaxType,
    22→    color: String
    23→}
    24→
    25→fn create_fvlang_highlighter() -> Vec<HighlightRule> {
    26→    vec![
    27→        HighlightRule {
    28→            pattern: "\\bfn\\b".to_string(),
    29→            syntax_type: SyntaxType::Keyword,
    30→            color: "#ff79c6".to_string()  // 핑크
    31→        },
    32→        HighlightRule {
    33→            pattern: "\\blet\\b".to_string(),
    34→            syntax_type: SyntaxType::Keyword,
    35→            color: "#ff79c6".to_string()
    36→        },
    37→        HighlightRule {
    38→            pattern: "\\bif\\b|\\belse\\b|\\bmatch\\b".to_string(),
    39→            syntax_type: SyntaxType::Keyword,
    40→            color: "#ff79c6".to_string()
    41→        },
    42→        HighlightRule {
    43→            pattern: "\\bstruct\\b|\\benum\\b|\\bimpl\\b".to_string(),
    44→            syntax_type: SyntaxType::Keyword,
    45→            color: "#ff79c6".to_string()
    46→        },
    47→        HighlightRule {
    48→            pattern: "\"[^\"]*\"".to_string(),
    49→            syntax_type: SyntaxType::String,
    50→            color: "#f1fa8c".to_string()  // 노랑
    51→        },
    52→        HighlightRule {
    53→            pattern: "//.*$".to_string(),
    54→            syntax_type: SyntaxType::Comment,
    55→            color: "#6272a4".to_string()  // 회색
    56→        },
    57→        HighlightRule {
    58→            pattern: "[0-9]+(\\.[0-9]+)?".to_string(),
    59→            syntax_type: SyntaxType::Number,
