    42→            result
    43→        }
    44→        BlockType::CodeBlock(code) => {
    45→            format!("```fvlang\n{}\n```", code)
    46→        }
    47→        BlockType::OutputBlock(output) => {
    48→            format!("```output\n{}\n```", output)
    49→        }
    50→        _ => String::new()
    51→    }
    52→}
