   130→    fn get_line(&self, line_num: i32) -> Option<String> {
   131→        let lines: Vec<&str> = self.content.lines().collect()
   132→        if line_num >= 0 && (line_num as usize) < lines.len() {
   133→            Some(lines[line_num as usize].to_string())
