   237→        // Right Panel: Code Editor + Results
   238→        html.push_str("<div class=\"right-panel\">\n")
   239→        html.push_str("<h2>Code Editor</h2>\n")
   240→        html.push_str("<pre class=\"code-editor\">\n")
   241→        html.push_str(&code_editor.render_with_syntax())
   242→        html.push_str("</pre>\n")
   243→
   244→        // Execution Results
   245→        if let Some(exec_result) = result {
   246→            html.push_str(&render_execution_result(exec_result))
   247→        }
   248→
   249→        html.push_str("</div>\n")
   250→        html.push_str("</div>\n")
   251→        html.push_str("</body>\n")
   252→        html.push_str("</html>\n")
   253→
   254→        html
   255→    }
   256→}
