   258→// ============================================================================
   259→// Main Editor
   260→// ============================================================================
   261→
   262→struct Editor {
   263→    state: EditorState,
   264→    config: EditorConfig,
   265→    layout: EditorLayout,
   266→    code_editor: CodeEditor
   267→}
   268→
   269→impl Editor {
   270→    fn new(config: EditorConfig) -> Editor {
   271→        let default_doc = Document {
   272→            title: "Untitled".to_string(),
   273→            blocks: Vec::new(),
   274→            metadata: Metadata {
   275→                version: "0.1.0".to_string(),
   276→                created: "2026-03-18".to_string(),
   277→                modified: "2026-03-18".to_string()
   278→            }
   279→        }
   280→
   281→        Editor {
   282→            state: EditorState {
   283→                document: default_doc,
   284→                current_file: "untitled.flmd".to_string(),
   285→                is_modified: false,
   286→                selected_block: None,
   287→                cursor_position: (0, 0)
   288→            },
   289→            config: config,
   290→            layout: EditorLayout::new(),
   291→            code_editor: CodeEditor::new("fvlang".to_string())
   292→        }
   293→    }
   294→
   295→    fn load_document(&mut self, content: String) -> Result<(), String> {
   296→        let doc = parse_flmd(content)?
   297→        self.state.document = doc
   298→        self.state.is_modified = false
   299→        Ok(())
   300→    }
   301→
   302→    fn set_code_block(&mut self, code: String) {
   303→        self.code_editor.set_content(code)
   304→        self.state.is_modified = true
   305→    }
   306→
   307→    fn select_block(&mut self, block_index: i32) {
   308→        self.state.selected_block = Some(block_index)
   309→    }
   310→
   311→    fn get_selected_code(&self) -> Option<String> {
   312→        if let Some(idx) = self.state.selected_block {
   313→            if idx >= 0 && (idx as usize) < self.state.document.blocks.len() {
   314→                match &self.state.document.blocks[idx as usize] {
   315→                    BlockType::CodeBlock(code) => {
   316→                        return Some(code.clone())
   317→                    }
   318→                    _ => {}
   319→                }
   320→            }
   321→        }
   322→        None
   323→    }
   324→
   325→    fn render_html(&self) -> String {
   326→        self.layout.render_html(
   327→            self.state.document.clone(),
   328→            self.code_editor.clone(),
   329→            None
   330→        )
   331→    }
   332→}
